import React from "react"
import Fade from "react-reveal/Fade"
import data from "../yourdata"

const imgProfile = "https://user-images.githubusercontent.com/23058601/152922506-f44c4da0-d0ea-4bef-869a-235cb30dcc2f.png"

const About = () => {
  return (
    <div className="section about-wrapper-section" id="about">
      <div className="container">
        <div className="about-container">
          <div className="about-content">
            <Fade bottom>
              <div className="section-badge">👨‍💻 About Me</div>
              <h2 className="about-heading">Passionate Software Developer</h2>
              <p className="about-text">{data.aboutParaOne}</p>
            </Fade>
          </div>
          
          <div className="about-image-card">
            <Fade bottom>
              <div className="image-frame">
                <img src={imgProfile} alt="Profile" className="profile-img" />
                <div className="image-glow"></div>
              </div>
            </Fade>
          </div>
        </div>
      </div>
    </div>
  )
}

export default About

