import React from "react"
import Fade from "react-reveal/Fade"
import scrollTo from "gatsby-plugin-smoothscroll"
import data from "../yourdata"

const Header = () => {
  return (
    <div className="section hero-section" id="home">
      <div className="hero-background-glow"></div>
      <div className="container">
        <div className="header-wrapper">
          <Fade bottom>
            <div className="section-badge">
              <span>👋</span> Hi there, I'm {data.name}
            </div>
          </Fade>
          
          <Fade bottom>
            <div className="heading-wrapper">
              <h1>
                {data.headerTagline[0]}. <br />
                <span className="gradient-text">{data.headerTagline[1]}</span> {data.headerTagline[2]}
              </h1>
            </div>
          </Fade>
          
          <Fade bottom>
            <p className="hero-paragraph">{data.headerParagraph}</p>
          </Fade>

          <Fade bottom>
            <div className="hero-cta-group">
              <button onClick={() => scrollTo("#work")} className="primary-btn">
                Explore Work <span>→</span>
              </button>
              <button onClick={() => scrollTo("#contact")} className="secondary-btn">
                Contact Me
              </button>
            </div>
          </Fade>
        </div>
      </div>
    </div>
  )
}

export default Header

